import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    arr = data[2:2 + n]

    prev = -1
    total = 0

    for a in arr:
        x = a
        y = m - a
        if x > y:
            x, y = y, x

        if x >= prev:
            chosen = x
        elif y >= prev:
            chosen = y
        else:
            sys.stdout.write("-1\n")
            return

        total += chosen
        prev = chosen

    sys.stdout.write(str(total) + "\n")

if __name__ == "__main__":
    solve()
